// Concept fixtures and session-only UI simulation. No API requests or real identity.
const $=s=>document.querySelector(s);
const taskId=new URLSearchParams(location.search).get('id')||'concept-library';
const currentTask=window.HWPrototype.tasks.find(t=>t.id===taskId);
const works=window.HWPrototype.worksByTask[taskId]||[];
function renderTask(){
 const title=currentTask?.title||'This prototype task is unavailable.';document.title=title+' — Human Worth';const heading=$('.task-header h1');heading.textContent=title;
 if(taskId==='concept-library'){heading.replaceChildren(document.createTextNode('A library is closing.'),document.createElement('br'),document.createTextNode('What do its readers need to know?'));}
 $('.eyebrow').firstChild.textContent='TASK / '+(currentTask?String(window.HWPrototype.tasks.indexOf(currentTask)+1).padStart(2,'0'):'—')+' ';
 if(!currentTask)return;
 $('.header-note .label').textContent=currentTask.category||'Concept task';
 $('.header-note p:nth-child(2)').textContent=currentTask.summary;
 $('#situation .lead').textContent=currentTask.summary;
 if(taskId!=='concept-library'){
 $('#situation h2').textContent='Background and requirements';const brief=$('.shared-brief');brief.replaceChildren();const label=document.createElement('p');label.className='label';label.textContent='Concept task brief';const text=document.createElement('p');text.style.whiteSpace='pre-line';text.textContent=currentTask.description;brief.append(label,text);
 $('#situation .section-body > .small').textContent='Local prototype brief only. Referenced source materials and works have not been supplied for this example.';
 }
}
const scenarios={anonymous:'Not signed in',eligible:'Signed in · can vote',voted:'Preference already saved',closed:'Permanently closed voting',restricted:'Other voting restriction',unavailable:'Task unavailable',loaderror:'Task loading failure',empty:'No approved works',balloterror:'Incomplete candidate load',conflict:'Next vote: version conflict',removed:'Next confirmation: chosen work unavailable',votefail:'Next vote: saving failure',statsfail:'Statistics fail after closing voting',commentfail:'Next comment: submission failure'};
let state={},epoch=0,trigger=null;
const dialog=$('#dialog');
function announce(text){$('#announcer').textContent=text;}
function closeDialog(){dialog.close();}
function openDialog(title,html){if(!dialog.open)trigger=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(trigger?.isConnected)trigger.focus({preventScroll:true});});$('#dialog-close').onclick=closeDialog;
function signIn(){openDialog('Try a signed-in session','<p>This prototype does not sign you into a real account. Continue to try the local voting, commenting and reporting states.</p><button class="button" id="demo-login">Continue in demo</button>');$('#demo-login').onclick=()=>{state.signed=true;updateEligibility();closeDialog();announce('Demo session active. No real account was used.');};}
function destination(name){openDialog(name,'<p>This related page is part of the agreed product scope. It is not implemented in this prototype. Nothing has been submitted or created.</p><p class="small">Return to this task to continue reading. Your local preference is preserved.</p><button class="button secondary" id="destination-close">Return to task</button>');$('#destination-close').onclick=closeDialog;}
// Local preview asset registry; no guessed download endpoint or automatic external fetch.
const localReaderAssets=new Map();
function appendArtifacts(root,artifacts=[]){for(const artifact of artifacts){
 if(artifact.kind==='link'){try{const url=new URL(artifact.url);if(!['http:','https:'].includes(url.protocol))continue;const a=document.createElement('a');a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';a.className='text-link';a.textContent='Open supporting material ↗';const p=document.createElement('p');p.append(a);root.append(p);}catch{} }
 else if(artifact.kind==='file'){const asset=localReaderAssets.get(artifact.assetId);if(asset&&asset.mime.startsWith('image/')){const img=document.createElement('img');img.src=asset.src;img.alt=asset.name||'Work material';img.addEventListener('error',()=>{const p=document.createElement('p');p.textContent='This material could not be loaded.';img.replaceWith(p);});root.append(img);}else{const p=document.createElement('p');p.className='small';p.textContent='File material: preview not supplied in this local prototype.';root.append(p);}}
}}
const reading={side:null,positions:{human:0,agent:0},visited:new Set()};
const chapterNames={human:'Human Work',agent:'Agent Work'};
const chapterNumber={human:'I',agent:'II'};
function chapterWorks(side){return state.noWorks||state.ballotError?[]:works.filter(w=>w.side===side&&!state.unavailableIds?.has(w.id));}
function renderWorks(){
 reading.side=null;$('#work-reader').hidden=true;$('#work-groups').hidden=false;
 $('#works-intro').textContent='Open a chapter, read each work, then return to your own judgment. Neither chapter implies a preference.';
 $('#works-state').hidden=!state.noWorks&&!state.ballotError;
 $('#works-message').textContent=state.noWorks?'Prototype placeholder: no works have been supplied for this task or scenario. Voting and statistics are unavailable.':'The complete candidate set could not be loaded. Reload before choosing a work.';
 $('#works-retry').hidden=state.noWorks;
 const root=$('#work-groups');root.replaceChildren();
 for(const side of ['human','agent']){
 const count=chapterWorks(side).length,chapter=document.createElement('section');chapter.className='chapter-cover';chapter.dataset.side=side;
 chapter.innerHTML='<div class="chapter-art" aria-hidden="true"><i></i><i></i><i></i></div><p class="chapter-kicker">Chapter '+chapterNumber[side]+'</p><h3>'+chapterNames[side]+'</h3><p class="chapter-description">'+(side==='human'?'Read the approaches attributed to people.':'Read the approaches attributed to agents.')+'</p><div class="chapter-bottom"><p class="small">'+(state.ballotError?'Works unavailable':count+' '+(count===1?'concept work':'concept works'))+'</p><button class="text-link" data-open-chapter="'+side+'" '+(!count?'disabled':'')+'>'+(count?'Open chapter →':'No works supplied')+'</button></div>';
 root.append(chapter);
 }
}
function showReading(focus=true,animate=false){
 const side=reading.side,items=chapterWorks(side);if(!items.length){renderWorks();return;}
 reading.positions[side]=Math.max(0,Math.min(reading.positions[side],items.length-1));const index=reading.positions[side],w=items[index];reading.visited.add(side);
 $('#work-groups').hidden=true;$('#work-reader').hidden=false;
 $('#reader-chapter').textContent='Chapter '+chapterNumber[side]+' / '+chapterNames[side];$('#reader-title').textContent=w.title;$('#reader-source').textContent=w.source||'';
 const content=$('#reader-content');content.replaceChildren();const text=document.createElement('p');text.textContent=w.text||w.description||'';content.append(text);appendArtifacts(content,w.artifacts);
 $('#reader-choose').dataset.choose=w.id;$('#reader-report').dataset.report=w.id;
 $('#reader-progress').textContent=(index+1)+' / '+items.length+' works';$('#reader-page').textContent='Work '+String(index+1).padStart(2,'0');
 $('#reader-prev').disabled=index===0;$('#reader-next').disabled=index===items.length-1;
 document.querySelectorAll('.reader-switch button').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.openChapter===side));b.disabled=!chapterWorks(b.dataset.openChapter).length;});
 updateEligibility();
 if(animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches)$('.book-spread').animate([{opacity:.65,transform:'translateY(4px)'},{opacity:1,transform:'translateY(0)'}],{duration:160,easing:'ease-out'});
 if(focus){$('#reader-title').focus({preventScroll:true});$('#work-reader').scrollIntoView({block:'start'});}
}
function leaveReading(){const side=reading.side;reading.side=null;$('#work-reader').hidden=true;$('#work-groups').hidden=false;$('#work-groups [data-open-chapter="'+side+'"]').focus({preventScroll:true});$('#work-groups').scrollIntoView({block:'start'});}
function turnWork(direction){const items=chapterWorks(reading.side);if(!items.length)return;const next=reading.positions[reading.side]+direction;if(next<0||next>=items.length)return;reading.positions[reading.side]=next;showReading(true,true);}
$('#works').addEventListener('click',e=>{const button=e.target.closest('[data-open-chapter]');if(!button||button.disabled)return;reading.side=button.dataset.openChapter;showReading();});
$('#reader-back').onclick=leaveReading;$('#reader-prev').onclick=()=>turnWork(-1);$('#reader-next').onclick=()=>turnWork(1);
$('#work-reader').addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.target.closest('input,textarea,select')||dialog.open)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();turnWork(e.key==='ArrowRight'?1:-1);}if(e.key==='Escape'){e.preventDefault();leaveReading();}});

function eligibleWorks(){return state.noWorks||state.ballotError?[]:works.filter(w=>!state.unavailableIds?.has(w.id));}
function voteBlocked(){return state.closed||state.restricted||state.noWorks||state.ballotError||state.conflict||state.busy;}
function updateEligibility(){
 const selected=works.find(w=>w.id===state.selected),saved=works.find(w=>w.id===state.vote),blocked=voteBlocked();
 $('#account-button').textContent=state.signed?'Account':'Sign in';
 $('#current-choice-title').textContent=selected?selected.title:'Choose a work as you read.';
 $('#current-choice-side').textContent=selected?chapterNames[selected.side]+(state.selected===state.vote?' · confirmed in this demo':' · staged selection'):'';
 $('#clear-choice').hidden=!selected;$('#clear-choice').disabled=state.busy;
 $('#vote-button').disabled=blocked||!selected||state.selected===state.vote;
 $('#vote-button').textContent=state.busy?'Confirming locally…':state.selected&&state.selected===state.vote?'Choice confirmed':'Confirm my choice';
 $('#eligibility-note').textContent=state.closed?'Voting is permanently closed for this task. Reading, discussion and adding works remain available.':state.restricted?'Voting is unavailable because of an account restriction.':state.ballotError||state.conflict?'The complete candidate set must be refreshed before confirming.':state.noWorks?'No work fixtures are available for selection in this state.':saved?'Confirmed in this local demo: '+saved.title+'. A different staged choice does not replace it until you confirm.':!state.signed?'You may stage a choice while signed out. Confirmation requires signing in to the demo.':'Your staged choice is not a submitted vote.';
 document.querySelectorAll('[data-choose]').forEach(b=>{b.disabled=blocked;b.setAttribute('aria-pressed',String(b.dataset.choose===state.selected));b.textContent=b.dataset.choose===state.selected?'Selected · Cancel selection':'Choose this work';});
 const unvisited=['human','agent'].find(side=>!reading.visited.has(side)&&chapterWorks(side).length);
 $('#chapter-reminder').hidden=!selected||!unvisited||reading.visited.size===0||blocked||state.selected===state.vote;
 if(unvisited){$('#chapter-reminder-text').textContent="You haven't explored "+chapterNames[unvisited]+' yet. You can read it before deciding, or continue with your current choice.';$('#explore-other').textContent='Explore '+chapterNames[unvisited];$('#explore-other').dataset.openChapter=unvisited;}
 $('#comment-button').textContent=state.signed?'Post local comment':'Sign in to comment';$('#statistics-button').disabled=state.statsBusy||state.noWorks||state.ballotError;
}
$('#clear-choice').onclick=()=>{if(state.busy)return;state.selected=null;$('#vote-feedback').textContent='Staged selection cancelled. Your submitted preference, if any, is unchanged.';updateEligibility();};

function resetScenario(name){if(!currentTask)name='unavailable';epoch++;reading.visited.clear();reading.positions={human:0,agent:0};state={selected:null,unavailableIds:new Set(),nextRemoved:name==='removed',signed:name!=='anonymous',closed:name==='closed',restricted:name==='restricted',vote:name==='voted'&&works.length?works[0].id:null,noWorks:!works.length||name==='empty',ballotError:name==='balloterror',failVote:name==='votefail',nextConflict:name==='conflict',failStats:name==='statsfail',failComment:name==='commentfail',busy:false,statsBusy:false,conflict:false};state.selected=state.vote;
 $('#page-state').hidden=!['unavailable','loaderror'].includes(name);$('#task-content').hidden=!$('#page-state').hidden;$('#page-state-title').textContent=name==='unavailable'?'This task is unavailable.':'The task could not be loaded.';$('#page-state-text').textContent=name==='unavailable'?'This example demonstrates unavailable or withdrawn content. No works or actions are exposed.':'Your connection or the service may be unavailable. Try the local loading demonstration again.';$('#page-retry').hidden=name==='unavailable';for(const s of ['#vote-feedback','#statistics-feedback','#comment-feedback'])$(s).textContent='';$('#statistics-output').hidden=true;$('#statistics-output').replaceChildren();$('#ballot-reload').hidden=true;resetDiscussion();$('#comment-body').value='';$('#comment-button').disabled=false;renderWorks();updateEligibility();}
$('#prototype-button').onclick=()=>{openDialog('Explore prototype states','<p>All data and actions are fictional. Applying a scenario resets the local session, including its preference and statistics access. Refreshing the page also resets the demo; a real account’s permanent restriction would not reset.</p><label for="scenario">Scenario</label><select id="scenario">'+Object.entries(scenarios).map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('')+'</select><button class="button" id="apply-scenario">Apply scenario</button>');$('#apply-scenario').onclick=()=>{resetScenario($('#scenario').value);closeDialog();announce('Local scenario changed.');};};
$('#account-button').onclick=()=>{if(!state.signed)return signIn();openDialog('Demo account','<p>No real account is connected.</p><div class="destination-list"><button class="text-link" data-destination="My Submissions">My Submissions</button><button class="text-link" data-destination="MCP Credentials">MCP Credentials</button><button class="text-link" id="demo-logout">Sign out of demo</button></div>');$('#demo-logout').onclick=()=>{state.signed=false;updateEligibility();closeDialog();};};
document.addEventListener('click',e=>{const destinationButton=e.target.closest('[data-destination]');if(destinationButton){destination(destinationButton.dataset.destination);return;}const choose=e.target.closest('[data-choose]');if(choose){if(voteBlocked())return;const id=choose.dataset.choose;if(!eligibleWorks().some(w=>w.id===id))return;state.selected=state.selected===id?null:id;$('#vote-feedback').textContent='';updateEligibility();announce(state.selected?'Selection staged only. Confirm below when ready.':'Selection cancelled. No submitted vote was changed.');}const report=e.target.closest('[data-report]');if(report)reportDialog(report.dataset.report);});
const delay=()=>new Promise(r=>setTimeout(r,350));
$('#vote-form').onsubmit=async e=>{
 e.preventDefault();if(voteBlocked()||!state.selected||state.selected===state.vote)return;
 if(!state.signed){signIn();return;}
 const picked=state.selected;if(!eligibleWorks().some(w=>w.id===picked)){state.selected=null;$('#vote-feedback').textContent='This work is no longer available to vote for. Please choose another work.';updateEligibility();return;}
 const version=epoch;state.busy=true;updateEligibility();await delay();if(version!==epoch)return;state.busy=false;
 if(state.closed||state.restricted||!state.signed){updateEligibility();return;}
 if(state.nextRemoved){state.nextRemoved=false;state.unavailableIds.add(picked);state.selected=null;state.noWorks=!works.some(w=>!state.unavailableIds.has(w.id));$('#vote-feedback').textContent='The chosen work is no longer eligible (local simulation). Nothing was submitted. Choose another available work.';renderWorks();}
 else if(state.nextConflict){state.nextConflict=false;state.conflict=true;$('#vote-feedback').textContent='The candidate or vote version changed (simulated 409). Nothing was submitted. Reload before confirming.';$('#ballot-reload').hidden=false;}
 else if(state.failVote){state.failVote=false;$('#vote-feedback').textContent='Local confirmation failed. Your staged choice is retained; retry when ready.';}
 else{state.vote=picked;$('#vote-feedback').textContent='Choice confirmed in this local demo only. No real vote was submitted.';}
 updateEligibility();
};
function reloadBallot(){state.conflict=false;state.ballotError=false;$('#ballot-reload').hidden=true;if(state.selected&&!eligibleWorks().some(w=>w.id===state.selected))state.selected=null;$('#vote-feedback').textContent='The complete local candidate set has been refreshed. Review your staged choice before confirming.';renderWorks();updateEligibility();$('#current-choice-title').setAttribute('tabindex','-1');$('#current-choice-title').focus({preventScroll:true});}

$('#ballot-reload').onclick=reloadBallot;$('#works-retry').onclick=reloadBallot;
async function accessStatistics(){const version=epoch;state.closed=true;state.statsBusy=true;updateEligibility();$('#statistics-feedback').textContent='Voting is now closed in this demo. Loading illustrative statistics…';await delay();if(version!==epoch)return;state.statsBusy=false;if(state.failStats){state.failStats=false;$('#statistics-feedback').textContent='Statistics could not be loaded. Voting remains permanently closed in this demo. Use View statistics to retry.';}else{const output=$('#statistics-output');output.innerHTML='<p class="label">Illustrative statistics · not real votes</p><p class="small">Fictional snapshot: 20 preferences. These values do not change when you try local voting.</p><table><caption class="sr-only">Fictional preferences for all four example works</caption><thead><tr><th scope="col">Work</th><th scope="col">Preferences</th><th scope="col">Share</th></tr></thead><tbody>'+works.map((w,i)=>'<tr><th scope="row">'+w.title+'</th><td>'+[6,4,5,5][i]+'</td><td>'+[30,20,25,25][i]+'%</td></tr>').join('')+'</tbody></table><p class="small">Human works: 10 / 50%. Agent works: 10 / 50%. No winner or ranking is inferred.</p>';output.hidden=false;$('#statistics-feedback').textContent='Illustrative snapshot displayed. Voting remains closed.';}updateEligibility();}
$('#statistics-button').onclick=()=>{if(!state.signed)return signIn();if(state.closed)return accessStatistics();openDialog('View statistics and close voting?','<p>This permanently removes your ability to vote or change your preference on this task. Any existing preference remains. You may still read, discuss and submit another work.</p><p><strong>This is a local simulation.</strong> No real account or vote is affected.</p><div class="actions"><button class="button" id="confirm-statistics">Close voting & view statistics</button><button class="text-link" id="cancel-statistics">Keep voting open</button></div>');$('#confirm-statistics').onclick=()=>{closeDialog();accessStatistics();};$('#cancel-statistics').onclick=closeDialog;};
function reportDialog(target){if(!state.signed)return signIn();openDialog('Report '+(target==='task'?'this task':'this work'),'<p>A real report would enter moderation; it would not automatically remove the content. This form demonstrates the interaction locally.</p><form id="report-form"><label for="report-reason">Reason</label><textarea id="report-reason" required rows="3"></textarea><button class="button secondary">Submit local report</button><p id="report-feedback" class="feedback" role="status"></p></form>');$('#report-form').onsubmit=e=>{e.preventDefault();if(!$('#report-reason').value.trim()){ $('#report-feedback').textContent='Please explain the reason.';return;}$('#report-feedback').textContent='Local report demonstrated. Nothing was sent to moderation.';$('#report-form button').disabled=true;};}
$('#add-work').onclick=openSubmission;$('#page-retry').onclick=async()=>{const version=epoch;$('#page-retry').disabled=true;$('#page-state-text').textContent='Loading local example…';await delay();if(version!==epoch)return;$('#page-retry').disabled=false;resetScenario('eligible');$('#prototype-button').focus();};
