const submissionDraft={side:'human',title:'',body:'',file:null};let submissionSerial=0;
// In-memory interaction only; deliberately no EntryInput serialization or transport.
async function simulateSubmission(fail){await delay();return {failed:fail};}
function openSubmission(){
 if(!currentTask)return;
 openDialog('Add a work','<button class="text-link" id="submission-back">← Back to Task Detail</button><div class="submission-task"><p class="label">For this task</p><h3 id="submission-task-title"></h3><details><summary>Task requirements</summary><p id="submission-requirements"></p></details></div><p class="small">Prototype · Try text or a local file. Nothing is uploaded or sent. Final fields will follow the submission interface.</p><form id="submission-form" novalidate><label for="submission-body">Your work</label><textarea id="submission-body" aria-describedby="submission-feedback" rows="6" placeholder="Place your work here…"></textarea><div class="submission-file"><label for="submission-file">Or choose a local file</label><input type="file" id="submission-file"><p class="small" id="submission-file-label"></p><button type="button" class="text-link" id="submission-remove">Remove file</button></div><details class="submission-options"><summary>Optional example details</summary><div class="submission-meta"><div><label for="submission-side">Work attributed to</label><select id="submission-side"><option value="human">Human</option><option value="agent">Agent</option></select></div><div><label for="submission-title">Work title (optional in demo)</label><input id="submission-title" type="text"></div></div></details><p class="small">New works must be reviewed before public display. This demo creates no submission or review status.</p><details class="submission-tests"><summary>Prototype test controls</summary><label class="demo-check"><input type="checkbox" id="submission-fail"> Simulate the next submission failing</label></details><div class="actions"><button class="button" id="submission-submit">Try local submission</button><button class="text-link" type="button" id="submission-login" hidden>Continue with demo sign-in</button></div><p id="submission-feedback" class="feedback" role="status"></p></form>');
 dialog.classList.add('submission-dialog');dialog.scrollTop=0;$('#submission-back').onclick=closeDialog;
 $('#submission-task-title').textContent=currentTask.title;$('#submission-requirements').textContent=currentTask.description;
 for(const key of ['side','title','body']){const input=$('#submission-'+key);input.value=submissionDraft[key];input.oninput=()=>submissionDraft[key]=input.value;}
 const fileLabel=()=>{$('#submission-file-label').textContent=submissionDraft.file?'Selected locally: '+submissionDraft.file.name+' · '+Math.ceil(submissionDraft.file.size/1024)+' KB. Not uploaded.':'No file selected. File types and limits are not defined by this prototype.';$('#submission-remove').hidden=!submissionDraft.file;};fileLabel();
 $('#submission-file').onchange=e=>{submissionDraft.file=e.target.files[0]||null;fileLabel();};$('#submission-remove').onclick=()=>{submissionDraft.file=null;$('#submission-file').value='';fileLabel();};
 $('#submission-login').onclick=()=>{state.signed=true;updateEligibility();$('#submission-login').hidden=true;$('#submission-feedback').textContent='Demo sign-in active. Review your work, then try the local submission again.';};
 $('#submission-form').onsubmit=async e=>{e.preventDefault();if($('#submission-submit').disabled)return;const feedback=$('#submission-feedback');if(!submissionDraft.body.trim()&&!submissionDraft.file){feedback.textContent='For this demo, add some work text or choose a local file.';$('#submission-body').setAttribute('aria-invalid','true');$('#submission-body').focus();return;}$('#submission-body').removeAttribute('aria-invalid');if(!state.signed){feedback.textContent='You are signed out. Continue with demo sign-in to try submitting. Your inputs are retained.';$('#submission-login').hidden=false;return;}const token=++submissionSerial,version=epoch,fail=$('#submission-fail').checked;$('#submission-fail').checked=false;$('#submission-submit').disabled=true;feedback.textContent='Simulating submission locally…';$('#submission-form').setAttribute('aria-busy','true');for(const el of $('#submission-form').querySelectorAll('input,textarea,select,#submission-remove'))el.disabled=true;const result=await simulateSubmission(fail);if(token!==submissionSerial||version!==epoch||!$('#submission-form'))return;$('#submission-submit').disabled=false;$('#submission-form').setAttribute('aria-busy','false');for(const el of $('#submission-form').querySelectorAll('input,textarea,select,#submission-remove'))el.disabled=false;if(!state.signed){feedback.textContent='The demo session ended. Your work is retained.';return;}feedback.textContent=result.failed?'Local simulation failed. Your text and selected file are retained. Try again.':'Local simulation complete. Nothing was uploaded, submitted or published. A real submission would require review.';};
}
dialog.addEventListener('close',()=>{submissionSerial++;dialog.classList.remove('submission-dialog');});
let discussion={version:0,db:[],items:[],nextCursor:null,loading:false,posting:false,failNext:false};
const commentOrder=(a,b)=>a.createdAt.localeCompare(b.createdAt)||a.id.localeCompare(b.id);
function exampleComments(){return ['I would start with the practical information a reader needs next.','The two approaches make different assumptions about what is already familiar. It helps to make those assumptions visible.','Clarity matters here, but so does what gets left out. I would look for a response that preserves the constraints without making the reader work to reconstruct them. A shorter answer is not automatically a clearer one.','I found it useful to return to the original task before choosing.','The wording changes how I understand the same facts.','I am still considering which approach makes the next step easiest.'].map((body,i)=>({id:'example-'+i,taskId,author:{id:'example-reader-'+i,displayName:'Example reader '+(i+1)},body,createdAt:new Date(Date.now()-(6-i)*300000).toISOString()}));}
function resetDiscussion(mode=taskId==='concept-library'?'samples':'empty'){$('#comment-button').disabled=false;$('#comment-body').readOnly=false;$('#comment-body').removeAttribute('aria-invalid');$('#comment-feedback').textContent='';$('#comment-view').hidden=true;$('#comment-list').replaceChildren();$('#comments-more').hidden=true;discussion={version:discussion.version+1,db:mode==='samples'?exampleComments():[],items:[],nextCursor:null,loading:false,posting:false,failNext:mode==='failure'};loadComments(true);}
function renderComments(){const list=$('#comment-list');list.replaceChildren();for(const c of discussion.items.sort(commentOrder)){const item=document.createElement('article');item.className='comment';item.id='comment-'+c.id;item.tabIndex=-1;const meta=document.createElement('p');meta.className='comment-meta';const author=document.createElement('span');author.textContent=c.author.displayName;const time=document.createElement('time');time.dateTime=c.createdAt;time.textContent=new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(c.createdAt));meta.append(author,time);const body=document.createElement('p');body.textContent=c.body;item.append(meta,body);list.append(item);}if(!discussion.items.length&&!discussion.loading){const empty=document.createElement('p');empty.className='small';empty.textContent='No comments in this local example yet. Start with your perspective on the task.';list.append(empty);}}
// Cursor and page shape mirror CommentPage; data stays in memory and no request is made.
async function mockCommentPage(cursor,limit){const fail=discussion.failNext;discussion.failNext=false;const snapshot=[...discussion.db];await delay();if(fail)throw Error('Local simulated failure');const sorted=snapshot.sort(commentOrder),start=cursor?sorted.findIndex(c=>c.id===cursor)+1:0,items=sorted.slice(start,start+limit);return {items,nextCursor:start+items.length<sorted.length?items.at(-1).id:null};}
async function loadComments(initial=false){if(discussion.loading)return;const version=discussion.version;discussion.loading=true;$('#comment-list').setAttribute('aria-busy','true');$('#comments-more').disabled=true;$('#comment-load-state').textContent=initial?'Loading local discussion…':'Loading more local comments…';try{const page=await mockCommentPage(initial?null:discussion.nextCursor,3);if(version!==discussion.version)return;const merged=new Map(discussion.items.map(c=>[c.id,c]));page.items.forEach(c=>merged.set(c.id,c));discussion.items=[...merged.values()];discussion.nextCursor=page.nextCursor;discussion.loading=false;renderComments();$('#comment-load-state').textContent=page.nextCursor?'More local comments are available.':discussion.items.length?'All local comments loaded.':'';$('#comments-more').hidden=!page.nextCursor;$('#comments-more').textContent='Load more';$('#comments-more').onclick=()=>loadComments();}catch{if(version!==discussion.version)return;discussion.loading=false;$('#comment-load-state').textContent='Local discussion could not load. Existing comments and your text are retained.';$('#comments-more').hidden=false;$('#comments-more').textContent='Retry loading';$('#comments-more').onclick=()=>loadComments(initial);}finally{if(version===discussion.version){discussion.loading=false;$('#comments-more').disabled=false;$('#comment-list').setAttribute('aria-busy','false');}}}
function initCommunity(){
 $('#comments-post-failure').onclick=()=>{state.failComment=true;$('#comment-feedback').textContent='The next local comment will fail. Your text will be retained for retry.';};
 $('#comments-signed-out').onclick=()=>{state.signed=false;updateEligibility();$('#comment-feedback').textContent='Demo signed out. You can keep writing; posting will offer a demo sign-in.';};
 $('#comments-samples').onclick=()=>resetDiscussion('samples');$('#comments-empty').onclick=()=>resetDiscussion('empty');$('#comments-failure').onclick=()=>{discussion.failNext=true;loadComments(!discussion.items.length);};
 $('#comment-form').onsubmit=async e=>{e.preventDefault();if(discussion.posting)return;const body=$('#comment-body').value.trim();if(!body){$('#comment-feedback').textContent='Write a comment before posting.';$('#comment-body').setAttribute('aria-invalid','true');$('#comment-body').focus();return;}$('#comment-body').removeAttribute('aria-invalid');if(!state.signed){$('#comment-feedback').textContent='Sign in to the demo, then post again. Your text is retained.';return signIn();}const version=discussion.version,session=epoch;discussion.posting=true;$('#comment-button').disabled=true;$('#comment-body').readOnly=true;$('#comment-feedback').textContent='Adding comment locally…';await delay();if(version!==discussion.version||session!==epoch)return;discussion.posting=false;$('#comment-button').disabled=false;$('#comment-body').readOnly=false;if(!state.signed){$('#comment-feedback').textContent='Sign in to the demo again. Your text is retained.';return;}if(state.failComment){state.failComment=false;$('#comment-feedback').textContent='Local comment failed. Your text is retained; please retry.';return;}const comment={id:'local-'+Date.now()+'-'+discussion.db.length,taskId,author:{id:'demo-you',displayName:'You · local demo'},body,createdAt:new Date().toISOString()};discussion.db.push(comment);discussion.items.push(comment);renderComments();$('#comment-body').value='';$('#comment-feedback').textContent='Added to this local list only. Nothing was published.';$('#comment-view').hidden=false;$('#comment-view').onclick=()=>{const item=document.getElementById('comment-'+comment.id);item?.focus();};};
}

initCommunity();renderTask();resetScenario('anonymous');
